import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseExamViewModel, ICourseExamDetailViewModel, ICourseExamViewModel } from '../../../../data/model/course/ExamModel';
import { DatePipe } from '@angular/common';

@Component({
  selector: 'app-degree',
  templateUrl: './degree.component.html',
  styleUrls: ['./degree.component.scss']
})
export class DegreeComponent implements OnInit {

  queryText = '';
  showSearchbar = false;
  examDetail: ICourseExamDetailViewModel;
  isLoading = true;

  constructor(
    private courseService: CourseService,
    private router: Router,
    public toastController: ToastController,
    private activatedRoute: ActivatedRoute,
    public datepipe: DatePipe,
    public loadingController: LoadingController
  ) {
  }

  ngOnInit(): void {
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  ionViewWillEnter() {

    this.activatedRoute.params.subscribe(params => {

      this.isLoading = true;
      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        this.router.navigateByUrl('/Page404');
      } else {

        SharedIonic.loading(this.loadingController);

        this.courseService.GetExamResultById(+id).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {

              this.examDetail = res.data;
              this.isLoading = false;
            }
            else {
              SharedIonic.toast(this.toastController, 'موردی یافت نشد');
              this.router.navigateByUrl('/Page404');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
            this.router.navigateByUrl('/Page404');
          }
        );
      }
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  printDegree() {
    window.print();
  }
}
